draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // character
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // mirror (symbolizing self-reflection)
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 - 20);
  ctx.lineTo(W/2 - 50, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2);
  ctx.lineTo(W/2 - 80, H/2);
  ctx.stroke();

  // integrity scale (moving up and down)
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 70, H/2 + 20 + 20*Math.sin(t), 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 70, H/2 + 20 - 20*Math.sin(t), 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + 70, H/2 + 20 + 10);
  ctx.lineTo(W/2 + 70, H/2 + 20 - 10);
  ctx.stroke();

  ctx.restore();
}
